import { Config } from "../Config.ada";
import { GameState } from "../Components/GameState.ada";
import { PlayerIntent } from "../Components/PlayerIntent.ada";

// Ready -> Playing -> Over -> Ready. Leaving Over (or pressing R) asks RestartSystem to reset the round.
@after(id: "runner.input")
@before(id: "runner.restart")
@system(scheduler: "update", id: "runner.phase")
class PhaseSystem {
    @query(GameState, PlayerIntent) var games;

    func update(context) {
        for (var game in games) {
            if (game.gameState.phase == Config.phaseReady && game.playerIntent.flap) {
                game.gameState.phase = Config.phasePlaying;
            }
            if (game.gameState.phase == Config.phaseOver && game.playerIntent.flap) {
                game.gameState.resetRequested = true;
            }
            if (game.playerIntent.restart) {
                game.gameState.resetRequested = true;
            }
        }
    }
}

files.Sources/Systems/RestartSystem.ada:
import { Config } from "../Config.ada";
import { Rules } from "../Rules.ada";
import { GameState } from "../Components/GameState.ada";
import { Obstacle } from "../Components/Obstacle.ada";
import { Player } from "../Components/Player.ada";

// Puts the round back to its start. Runs once for every reset request, including the one at launch.
@after(id: "runner.phase")
@before(id: "runner.flight")
@system(scheduler: "update", id: "runner.restart")
class RestartSystem {
    @query(GameState) var games;
    @query(Player, Transform) var players;
    @query(Obstacle, Transform) var obstacles;

    func update(context) {
        var requested = false;
        for (var game in games) { requested = game.gameState.resetRequested; }
        if (!requested) return;

        for (var row in players) {
            row.player.velocity = 0.0;
            row.transform.position = [Config.playerX, Config.playerStartY, 0.0];
        }
        for (var row in obstacles) {
            var gap = Rules.gapFor(row.obstacle.slot);
            row.obstacle.gapY = gap;
            row.obstacle.passed = false;
            row.transform.position = [Config.obstacleStartX + row.obstacle.slot * Config.obstacleSpacing, gap, 0.0];
        }
        for (var game in games) {
            game.gameState.phase = Config.phaseReady;
            game.gameState.score = 0;
            game.gameState.nextSequence = Config.obstacleCount;
            game.gameState.resetRequested = false;
        }
    }
}

files.Sources/Systems/ScoreSystem.ada:
import { Config } from "../Config.ada";
import { Rules } from "../Rules.ada";
import { Cues } from "../Components/Cues.ada";
import { GameState } from "../Components/GameState.ada";
import { Obstacle } from "../Components/Obstacle.ada";

// One point for every obstacle the player gets past.
@after(id: "runner.collision")
@before(id: "runner.audio")
@system(scheduler: "update", id: "runner.score")
class ScoreSystem {
    @query(GameState, Cues) var games;
    @query(Obstacle, Transform) var obstacles;

    func update(context) {
        var playing = false;
        for (var game in games) { playing = game.gameState.phase == Config.phasePlaying; }
        if (!playing) return;

        var passed = 0;
        for (var row in obstacles) {
            if (Rules.hasPassed(row.transform.position[0], row.obstacle.passed)) {
                row.obstacle.passed = true;
                passed += 1;
            }
        }
        if (passed > 0) {
            for (var game in games) {
                game.gameState.score += passed;
                game.cues.score = true;
            }
        }
    }
}

